def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = {(r-r0, c-c0) for r, c in pts}
    H = max(r for r, c in shape) + 1
    W = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h-H+1):
        for c in range(w-W+1):
            if (r, c) == (r0, c0):
                continue
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = 2
    return out

